const issue = $json;
const setup = $('Set Mode + IDs').first().json;

const issueTitle = issue.title || '';
const issueBody = issue.body || '';
const labels = (issue.labels || []).map(l => l.name || '');

const prompt = `
You are an AI software testing planning assistant for a university software engineering project.

An issue has been created. Based on the issue title and description, generate a testing-oriented planning comment.

Issue Title: ${issueTitle}
Issue Body: ${issueBody}
Labels: ${labels.join(', ') || 'none'}

Return your answer in markdown with these sections only:

## AI Issue Testing Plan

### Likely Affected Areas
List the parts of the system likely impacted.

### Acceptance Criteria Suggestions
Give 4 to 6 clear acceptance criteria.

### Priority Test Checklist
Provide a checklist:
- [ ] item (test type)

Include:
- happy path
- edge cases
- invalid input
- regression risk

### Suggested Prompt for Implementing Tests
Write 1 strong prompt for generating the most useful tests for this issue.

Keep it specific and practical.
`;

return [{
  json: {
    repoOwner: setup.repoOwner,
    repoName: setup.repoName,
    issueNumber: setup.issueNumber,
    issueTitle,
    issueBody,
    issueUrl: issue.html_url,
    issueBotMarker: setup.issueBotMarker,
    aiPrompt: prompt
  }
}];

const aiOutput = $json.output || $json.text || $json.response || 'No AI output generated.';
const meta = $('Build Issue Prompt').first().json;

const commentBody = [
  '## AI-ISSUE-TEST-PLAN',
  '',
  `**Issue:** #${meta.issueNumber} - ${meta.issueTitle}`,
  `**Issue Link:** ${meta.issueUrl}`,
  '',
  aiOutput,
  '',
  '---',
  '_Generated by n8n AI planning workflow_'
].join('\n');

return [{
  json: {
    repoOwner: meta.repoOwner,
    repoName: meta.repoName,
    issueNumber: meta.issueNumber,
    commentBody
  }
}];

const pr = $json;
const setup = $('Set Mode + IDs').first().json;

const prBody = pr.body || '';
const prTitle = pr.title || '';

const match = prBody.match(/(?:close[sd]?|fix(?:e[sd])?|resolve[sd]?|related to)\s+#(\d+)/i);
const linkedIssueNumber = match ? Number(match[1]) : null;

return [{
  json: {
    repoOwner: setup.repoOwner,
    repoName: setup.repoName,
    prNumber: setup.prNumber,
    prTitle,
    prBody,
    prUrl: pr.html_url,
    author: pr.user?.login || 'unknown',
    baseBranch: pr.base?.ref || '',
    headBranch: pr.head?.ref || '',
    headSha: pr.head?.sha || '',
    linkedIssueNumber,
    prBotMarker: setup.prBotMarker
  }
}];

const issue = $json;
const pr = $('Parse Linked Issue').first().json;

return [{
  json: {
    ...pr,
    linkedIssueTitle: issue.title || '',
    linkedIssueBody: issue.body || '',
    linkedIssueUrl: issue.html_url || '',
  }
}];

const pr = $json;

return [{
  json: {
    ...pr,
    linkedIssueTitle: '',
    linkedIssueBody: '',
    linkedIssueUrl: '',
  }
}];

const files = $input.all().map(item => item.json);
const meta = $('Merge Issue Context Result').first().json;

const filenames = files.map(f => f.filename || '');
const title = (meta.prTitle || '').toLowerCase();

const hasPath = (keyword) => filenames.some(f => f.toLowerCase().includes(keyword));
const titleHas = (keyword) => title.includes(keyword);

let categories = [];
let risk = 'Low';

if (
  titleHas('auth') || titleHas('login') || titleHas('register') ||
  hasPath('auth') || hasPath('login') || hasPath('register')
) categories.push('auth');

if (
  titleHas('payment') || titleHas('checkout') || titleHas('braintree') ||
  hasPath('payment') || hasPath('checkout') || hasPath('braintree')
) categories.push('payment');

if (
  titleHas('product') || hasPath('product')
) categories.push('product');

if (
  hasPath('client/src/pages') || hasPath('client/src/components')
) categories.push('frontend-ui');

if (
  hasPath('controllers/') || hasPath('routes/') || hasPath('models/') || hasPath('middlewares/')
) categories.push('backend-api');

if (
  filenames.length > 0 &&
  filenames.every(f => f.endsWith('.test.js') || f.includes('_tests_'))
) categories.push('testing-only');

if (titleHas('fix') || titleHas('bug')) categories.push('bugfix');
if (titleHas('refactor') || titleHas('cleanup')) categories.push('refactor');

categories = [...new Set(categories)];

const highRiskSignals =
  categories.includes('payment') ||
  categories.includes('auth') ||
  filenames.some(f => /controller|middleware|routes|checkout|payment|auth/i.test(f));

const medRiskSignals =
  categories.includes('backend-api') ||
  categories.includes('product') ||
  filenames.length > 5;

if (highRiskSignals) risk = 'High';
else if (medRiskSignals) risk = 'Medium';

let diffText = '';
for (const file of files) {
  const patch = (file.patch || '_No patch available._').replace(/```/g, "'''");
  diffText += `### File: ${file.filename}\n\n\`\`\`diff\n${patch}\n\`\`\`\n\n---\n\n`;
}

return [{
  json: {
    ...meta,
    categories,
    risk,
    filenames,
    diffText
  }
}];

const data = $json;

const prompt = `
You are an AI software testing reviewer for a university software engineering project.

Analyze this pull request and produce a concise, practical testing report.

Linked Issue Title: ${data.linkedIssueTitle || 'None'}
Linked Issue Body: ${data.linkedIssueBody || 'None'}

PR Title: ${data.prTitle}
PR Body: ${data.prBody}
Categories: ${data.categories.join(', ') || 'general'}
Risk Level: ${data.risk}

Changed Files:
${data.filenames.map(f => `- ${f}`).join('\n')}

Code Diffs:
${data.diffText}

Return your answer in markdown with these sections only:

## AI-Driven Testing Report

### Linked Issue Alignment
State whether the PR appears aligned with the linked issue.

### PR Classification
- Category
- Risk level
- Main modules affected

### Change Summary
Summarize what changed in 3 to 5 bullets.

### Recommended Test Focus
State what kinds of tests are most important.

### Priority Test Ideas
Provide a checklist:
- [ ] item (test type)

At least 6 items.

### Suggested Prompt for Writing Tests
Write 1 strong prompt for generating the most important tests.

### Notes for Reviewers
Mention blind spots or regression risks.
`;

return [{
  json: {
    ...data,
    aiPrompt: prompt
  }
}];

const ai = $json;
const pr = $('Build PR + Diff Context').first().json;

const aiOutput =
  ai.output ||
  ai.text ||
  ai.response ||
  ai.content ||
  'No AI output generated.';

const reviewText = String(aiOutput);

// derive a simple overall status from AI output
let overallStatus = '⚠️ REVIEW NEEDED';
if (reviewText.includes('### Review Status') && reviewText.match(/OK/i)) {
  overallStatus = '✅ OK';
}
if (reviewText.includes('HIGH RISK') || pr.risk === 'High') {
  overallStatus = '❌ HIGH RISK';
}

const linkedIssueDetected = pr.linkedIssueNumber ? 'Yes' : 'No';

const keyLines = reviewText
  .split('\n')
  .filter(line =>
    line.trim().startsWith('- ') ||
    line.trim().startsWith('[ ]') ||
    line.trim().startsWith('- [ ]')
  )
  .slice(0, 8);

const fallbackLines = [
  `- PR is ${pr.linkedIssueNumber ? 'linked to issue #' + pr.linkedIssueNumber : 'not linked to an issue'}`,
  `- Risk level assessed as ${pr.risk}`,
  `- Categories: ${pr.categories.join(', ') || 'general'}`,
  `- ${pr.changedFilesCount} changed file(s), ${pr.changedTestFilesCount} changed test file(s)`,
];

const excerpt = (keyLines.length ? keyLines : fallbackLines).join('\n');

const commentBody = [
  '## AI Test Review Summary',
  '',
  `**Overall status:** ${overallStatus}`,
  `**Linked issue detected:** ${linkedIssueDetected}`,
  `**Risk level:** ${pr.risk}`,
  `**Changed files:** ${pr.changedFilesCount}`,
  `**Changed test files:** ${pr.changedTestFilesCount}`,
  '',
  '**Key output:**',
  '```text',
  excerpt,
  '```',
  '',
  aiOutput,
  '',
  '---',
  '_Generated by n8n AI-driven testing workflow_'
].join('\n');

return [{
  json: {
    repoOwner: pr.repoOwner,
    repoName: pr.repoName,
    prNumber: pr.prNumber,
    commentBody,
    prBotMarker: pr.prBotMarker
  }
}];

const comments = $input.all().map(i => i.json);
const marker = $('Set Mode + IDs').first().json.prBotMarker;

const existing = comments.find(c =>
  c.body && c.body.includes(marker)
);

return [{
  json: {
    existingCommentId: existing ? existing.id : null
  }
}];
